#include "simulator.hpp"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <random>
#include <stdexcept>
#include <vector>
namespace queueing {namespace {struct Job{double arrival,service;int priority,index;};}
Summary simulate(const Config& c){if(c.customers<1||c.servers<1||c.arrival_rate<=0||c.service_rate<=0)throw std::invalid_argument("positive customers, servers, and rates required");std::mt19937_64 rng(c.seed);std::exponential_distribution<double> arrivals(c.arrival_rate),services(c.service_rate);std::uniform_int_distribution<int> priorities(1,5);std::vector<Job> jobs;double t=0;for(int i=0;i<c.customers;i++){t+=arrivals(rng);jobs.push_back({t,services(rng),priorities(rng),i});}std::vector<double> free(c.servers,0),waits;double busy=0,makespan=0;std::vector<Job> pending;std::size_t next=0,done=0;while(done<jobs.size()){double next_free=*std::min_element(free.begin(),free.end());double clock=pending.empty()&&next<jobs.size()?std::max(next_free,jobs[next].arrival):next_free;while(next<jobs.size()&&jobs[next].arrival<=clock){pending.push_back(jobs[next++]);}if(pending.empty())continue;auto chosen=pending.begin();if(c.policy==Policy::shortest)chosen=std::min_element(pending.begin(),pending.end(),[](auto&a,auto&b){return a.service<b.service;});if(c.policy==Policy::priority)chosen=std::max_element(pending.begin(),pending.end(),[](auto&a,auto&b){return a.priority<b.priority;});auto server=std::min_element(free.begin(),free.end());double start=std::max(*server,chosen->arrival);waits.push_back(start-chosen->arrival);busy+=chosen->service;*server=start+chosen->service;makespan=std::max(makespan,*server);pending.erase(chosen);done++;}std::sort(waits.begin(),waits.end());double sum=0;for(double w:waits)sum+=w;return{sum/waits.size(),waits[static_cast<std::size_t>(.95*(waits.size()-1))],std::min(1.0,busy/(makespan*c.servers)),makespan};}
Config read_config(const std::string& path){std::ifstream f(path);if(!f)throw std::runtime_error("cannot open config");Config c;std::string line;while(std::getline(f,line)){auto p=line.find('=');if(p==std::string::npos||line.starts_with('#'))continue;auto k=line.substr(0,p),v=line.substr(p+1);if(k=="customers")c.customers=std::stoi(v);else if(k=="servers")c.servers=std::stoi(v);else if(k=="arrival_rate")c.arrival_rate=std::stod(v);else if(k=="service_rate")c.service_rate=std::stod(v);else if(k=="seed")c.seed=std::stoull(v);else if(k=="policy")c.policy=v=="shortest"?Policy::shortest:v=="priority"?Policy::priority:Policy::fifo;else throw std::invalid_argument("unknown config key: "+k);}return c;}
std::string policy_name(Policy p){return p==Policy::fifo?"fifo":p==Policy::shortest?"shortest":"priority";}}
